using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml;
using System.Xml.Xsl;
using Sunplus.Shared.ViewLogLib.Entities;

using System.Collections.Specialized;
using System.Text.RegularExpressions;
using Sunplus.Shared.ViewLogLib.Services;

namespace Sunplus.Shared.ViewLogLib
{
    public static class Extensions
    {
        public static void Load(this XslCompiledTransform xslCompiledTransform, int actionId)
        {
            if (actionId < 0)
                return;

            ILogActionService logActionService = new LogActionService();
            LogAction logAction = logActionService.GetById(actionId);

            if (logAction != null && !string.IsNullOrEmpty(logAction.XsltContent))
            {
                using (var xslStream = new MemoryStream(ASCIIEncoding.Default.GetBytes(logAction.XsltContent)))
                {
                    XmlReader xsltReader = XmlReader.Create(xslStream);
                    xslCompiledTransform.Load(xsltReader);
                }
            }
        }
    }
}
